<script setup>
import { onMounted, ref, computed, nextTick } from 'vue'
import { collection, getDocs } from 'firebase/firestore'
import { db } from '../firebase.js'
import { useRouter } from 'vue-router'

const router = useRouter()
const items = ref([])
const hoveredKey = ref(null)
const textWidths = ref({}) // larghezza reale misurata di ogni titolo, in unità SVG

async function loadItems() {
  const snapshot = await getDocs(collection(db, 'items'))
  items.value = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }))
}

onMounted(loadItems)

function getSiteKey(id) {
  return id.replace(/-\d+$/, '')
}

const SITE_POSITIONS = {
  'lapa-do-penhasco': { x: 1090, y: 758 },
  'cachoeira-do-funil': { x: 1105, y: 780 },
  'caverna-do-bora-quatro': { x: 1120, y: 802 },
  'gruta-do-convento': { x: 1345, y: 630 },
  'toca-da-barriguda': { x: 1330, y: 650 },
  'toca-da-boa-vista': { x: 1310, y: 665 },
  'toca-dos-ossos': { x: 1275, y: 710 },
  'lapa-dos-brejoes': { x: 1253, y: 720 },
  'gruta-lapa-doce': { x: 1270, y: 780 },
  'lapa-do-bode': { x: 1295, y: 805 }
}

const LABEL_OFFSETS = {
  'gruta-do-convento': { dx: -60, dy: -95 },
  'toca-da-barriguda': { dx: 10, dy: 90 },
  'toca-da-boa-vista': { dx: 130, dy: 10 },
  'toca-dos-ossos': { dx: 120, dy: 10 },
  'lapa-dos-brejoes': { dx: -150, dy: -20 },
  'gruta-lapa-doce': { dx: 10, dy: -90 },
  'lapa-do-bode': { dx: 130, dy: 40 },
  'lapa-do-penhasco': { dx: -140, dy: -40 },
  'cachoeira-do-funil': { dx: -100, dy: 60 },
  'caverna-do-bora-quatro': { dx: -90, dy: 30 }
}

function geoToSvg(lat, lng) {
  const latMax = 5.3
  const latMin = -33.8
  const lngMin = -73.9
  const lngMax = -28.8
  const x = ((lng - lngMin) / (lngMax - lngMin)) * 1579
  const y = ((latMax - lat) / (latMax - latMin)) * 1658
  return { x, y }
}

const BAHIA_SITES = ['gruta-do-convento', 'toca-da-barriguda', 'toca-da-boa-vista', 'toca-dos-ossos', 'lapa-dos-brejoes', 'gruta-lapa-doce', 'lapa-do-bode']

const groupedPins = computed(() => {
  const groups = new Map()

  for (const item of items.value) {
    const siteKey = getSiteKey(item.id)

    if (!groups.has(siteKey)) {
      let position = SITE_POSITIONS[siteKey]

      if (!position) {
        const lat = item.coordinates?.latitude
        const lng = item.coordinates?.longitude
        if (lat == null || lng == null) continue
        position = geoToSvg(lat, lng)
      }

      groups.set(siteKey, {
        siteKey,
        x: position.x,
        y: position.y,
        title: item.title || siteKey,
        items: []
      })
    }
    groups.get(siteKey).items.push(item)
  }

  return Array.from(groups.values())
})

const PIN_RADIUS = 11
const PIN_GAP = 14
const DIAG_LENGTH = 40

function estimateTextWidth(text) {
  return (text || '').length * 6.5
}

function leaderLine(group) {
  const offset = LABEL_OFFSETS[group.siteKey] || { dx: 130, dy: -20 }
  const signX = Math.sign(offset.dx) || 1
  const signY = Math.sign(offset.dy) || 0

  const elbow = {
    x: group.x + signX * DIAG_LENGTH,
    y: group.y + signY * DIAG_LENGTH
  }

  const measured = textWidths.value[group.siteKey]
  const textWidth = measured != null ? measured : estimateTextWidth(group.title)
  const end = {
    x: elbow.x + signX * textWidth,
    y: elbow.y
  }

  const vx = elbow.x - group.x
  const vy = elbow.y - group.y
  const len = Math.hypot(vx, vy) || 1
  const start = {
    x: group.x + (vx / len) * (PIN_RADIUS + PIN_GAP),
    y: group.y + (vy / len) * (PIN_RADIUS + PIN_GAP)
  }

  return { start, elbow, end, signX }
}

function measureLabel(el, siteKey) {
  if (!el) return
  nextTick(() => {
    try {
      const len = el.getComputedTextLength()
      if (len && textWidths.value[siteKey] !== len) {
        textWidths.value = { ...textWidths.value, [siteKey]: len }
      }
    } catch (e) {
      // ignora se il browser non supporta la misura in questo momento
    }
  })
}

function onPinClick(group) {
  const firstItem = group.items[0]
  router.push({ name: 'itemDetail', params: { id: firstItem.id } })
}
</script>

