        <g v-for="(group, index) in groupedPins" :key="index">
          <g
            style="cursor: pointer;"
            @click="onPinClick(group)"
            @mouseenter="hoveredKey = group.siteKey"
            @mouseleave="hoveredKey = null"
          >
            <circle
              :cx="group.x"
              :cy="group.y"
              r="11"
              fill="white"
              :stroke="BAHIA_SITES.includes(group.siteKey) ? '#366146' : '#343434'"
              stroke-width="1.5"
              style="filter: drop-shadow(0 2px 6px rgba(0,0,0,0.15));"
            />
            <text
              :x="group.x"
              :y="group.y + 4"
              text-anchor="middle"
              font-family="Jura"
              font-weight="700"
              font-size="13"
              :fill="BAHIA_SITES.includes(group.siteKey) ? '#366146' : '#343434'"
              style="pointer-events: none;"
            >{{ group.items.length }}</text>
          </g>

          <!-- Linea guida spezzata (diagonale + orizzontale) + titolo -->
          <!-- Colore: bianco con mix-blend-mode "difference", che si inverte automaticamente
               in nero su sfondi chiari e resta chiaro su sfondi scuri/verdi -->
          <g v-if="hoveredKey === group.siteKey" style="pointer-events: none;">
            <path
              :d="`M ${leaderLine(group).start.x} ${leaderLine(group).start.y} L ${leaderLine(group).elbow.x} ${leaderLine(group).elbow.y} L ${leaderLine(group).end.x} ${leaderLine(group).end.y}`"
              fill="none"
              stroke="white"
              stroke-width="2"
              stroke-linejoin="round"
              stroke-linecap="round"
              style="mix-blend-mode: difference;"
            />
            <text
              :ref="(el) => measureLabel(el, group.siteKey)"
              :x="leaderLine(group).elbow.x"
              :y="leaderLine(group).elbow.y - 12"
              :text-anchor="leaderLine(group).signX > 0 ? 'start' : 'end'"
              font-family="Aeonik, sans-serif"
              font-size="16"
              fill="white"
              style="mix-blend-mode: difference;"
            >{{ group.title }}</text>
          </g>
        </g>
      </svg>
    </div>

    <!-- Pannello di testo a destra: stessi margini del titolo nelle schede grotte, mirrorati a destra -->
    <div style="position: fixed; top: 2rem; right: 3rem; width: 290px; font-family: 'Aeonik', sans-serif; font-size: 16px; line-height: 1.2; color: #343434; z-index: 1;">
      <p style="margin: 0 0 32px 0;">
        Field surveys systematically map ten key hypogean environments across central-eastern Brazil.
      </p>
      <p style="margin: 0 0 32px 0;">
        The first seven cavities - <span style="color: #afafaf;">Gruta do Convento, Toca da Barriguda, Toca da Boa Vista, Toca dos Ossos, Lapa dos Brejões, Gruta Lapa Doce, and Lapa do Bode</span>—are located within the state of <span style="color: #afafaf;">Bahia</span>. The remaining three systems - <span style="color: #afafaf;">Lapa do Penhasco, Cachoeira do Funil, and Caverna do Borá Quatro</span> - belong to the state of <span style="color: #afafaf;">Goiás</span>.
      </p>
      <p style="margin: 0;">
        For all cataloged cavities, the archive preserves high-resolution structural and photographic records of each subterranean environment.
      </p>
    </div>

    <!-- Crediti in basso, centrati -->
    <div style="position: fixed; bottom: 2rem; left: 50%; transform: translateX(-50%); z-index: 1; text-align: center; font-family: 'Jura', sans-serif; font-size: 0.7rem; letter-spacing: 0.03em; color: #a3a3a3; line-height: 1.6;">
      <p style="margin: 0;">Speleo_Archive</p>
      <p style="margin: 0;">Designed by Paola Fioraso</p>
    </div>
  </div>
